import{_ as r,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-07-18 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-07-18 :: Ceph Performance Meeting","date":"2019-07-18T00:00:00.000Z","updated":"2019-07-22T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","纠错码","复制","快照","克隆","瘦分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","故障域","恢复","弹性","负载均衡","缓存","压缩","数据去重","分层","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-18_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-07-18_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-07-18_-_-_Ceph_Performance_Meeting.md"};function s(o,e,p,n,g,c){return l(),a("div",null,[...e[0]||(e[0]=[t("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2019年7月18日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Adam, Sage, Igor, Patrick, Lucas, Marcus, Bella, Alex, David 等</p><p><strong>会议主题</strong>： Ceph 项目进展、技术讨论、行动计划</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 项目进展</strong></p><ul><li>Adam 近期提交了三个新的 Pull Request (PR) 用于图表工作，令人兴奋。</li><li>Sage 正在审查 Adam 的 PR，并希望尽快将其集成到自己的工作中。</li><li>Igor 的 PR 是一个很好的发展方向，团队将尝试使其更明确。</li><li>Patrick 和 Sage 就 AppTracker 的 PR 进行了讨论，讨论了字符串视图和动态事件的接口问题。</li><li>Sage 认为应该将字符串视图和动态事件分开，以避免复制和优化性能。</li><li>团队将进行更大范围的审查，以确定动态事件的接口应该是什么样子，并避免在一般情况下进行复制。</li><li>Sage 认为应该去掉动态事件，只传递信息。</li><li>Sage 和 Adam 正在合作解决 RocksDB 的复制问题。</li><li>团队正在讨论将 RocksDB 的 delete range 功能集成到 Nautilus 中。</li><li>Sage 认为应该将 RocksDB 5.18.12 版本的 delete range 功能集成到 Nautilus 中。</li><li>团队正在讨论如何测试 RocksDB 的 delete range 功能。</li></ul><p><strong>二、技术讨论</strong></p><ul><li>Sage 讨论了 RocksDB 的 OpTracker 性能问题，认为当前 OpTracker 对随机写入的性能影响很大。</li><li>团队讨论了 OpTracker 的改进方案，包括使用采样和优化 OpTracker 代码。</li><li>Sage 认为应该修复 OpTracker 中的明显问题，例如字符串复制，而不是完全重写代码。</li><li>团队讨论了将 OpTracker 的快速锁应用于其他地方的可能性。</li></ul><p><strong>三、行动计划</strong></p><ul><li>Sage 和 Adam 将继续合作解决 RocksDB 的复制问题。</li><li>团队将进行更大范围的审查，以确定动态事件的接口应该是什么样子，并避免在一般情况下进行复制。</li><li>Sage 将与团队讨论 OpTracker 的改进方案。</li><li>团队将测试 RocksDB 的 delete range 功能，并决定是否将其集成到 Nautilus 中。</li><li>团队将讨论如何将 RocksDB 的 OpTracker 的快速锁应用于其他地方。</li></ul><p><strong>四、其他事项</strong></p><ul><li>Sage 和 Bella 将讨论 Jenkins 集成事宜。</li><li>Marcus 将分享关于 Tableau 存储的跟踪信息。</li></ul><p><strong>五、会议总结</strong></p><p>本次会议讨论了 Ceph 项目的进展、技术讨论和行动计划。团队将继续努力解决各种问题，并推动 Ceph 项目的进展。</p>",16)])])}const d=r(i,[["render",s]]);export{u as __pageData,d as default};
